/* ---------- ask before an action that changes something: any button with data-ask="Title|Text" ---------- */
let ASK=null;
document.addEventListener("click",e=>{const b=e.target.closest&&e.target.closest("[data-ask]");if(!b||b._ok)return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();askOpen(b)},true);
function askOpen(b){askClose();const[ti,tx,k]=b.dataset.ask.split("|"),el=document.createElement("div");el.className="askc";el.innerHTML=`<div class="askb" role="alertdialog" aria-label="${esc(ti)}"><b>${esc(ti)}</b><div class="sm">${esc(tx||"")}</div><div class="askf"><button type="button" class="btn o s" data-ask-no>Cancel</button><button type="button" class="btn s ${k=="danger"?"r":""}" data-ask-yes>Yes, do it</button></div></div>`;
el.addEventListener("click",ev=>{if(ev.target.closest("[data-ask-yes]")){askClose();b._ok=true;b.click();setTimeout(()=>{b._ok=false},0)}else if(ev.target.closest("[data-ask-no]")||ev.target===el)askClose()});
document.body.appendChild(el);ASK=el;requestAnimationFrame(()=>el.classList.add("in"));const y=el.querySelector("[data-ask-yes]");if(y)y.focus()}
function askClose(){if(ASK){ASK.remove();ASK=null}}
document.addEventListener("keydown",e=>{if(ASK&&e.key=="Escape"){e.stopPropagation();askClose()}},true);
