async function uploadDocs(txId,files){const out=[];for(const fl of files){const r=await fetch(`/api/transactions/${txId}/documents`,{method:"POST",headers:{"x-filename":encodeURIComponent(fl.name),"content-type":fl.type||"application/octet-stream"},body:fl});if(!r.ok)throw new Error("upload failed");out.push(await r.json())}return out}
