{const lim=new Date(NOW-45*864e5).toISOString().slice(0,10);S.tx.forEach(t=>{if(t.d<lim||t.virtual)return;const j=jarSuggest(t);if(j)add("jar-"+t.id+"-"+j.id,"jars","med","Paid from a jar?",`${dn(t)} · ${fm(Math.abs(t.a))} looks like it came out of ${j.n}, because similar payments were attached to it. Attach it to the jar to keep the jar balance right.`,"tx",{attach:t.id})})}
