const b64u=x=>{const p="=".repeat((4-x.length%4)%4),r=atob((x+p).replace(/-/g,"+").replace(/_/g,"/"));return Uint8Array.from(r,c=>c.charCodeAt(0))};
async function pushReg(){return navigator.serviceWorker&&await navigator.serviceWorker.getRegistration()}
async function pushRefresh(){const el=$("pushSt");if(!el)return;if(!("PushManager" in window)||!navigator.serviceWorker){el.textContent=window.isSecureContext?"This browser does not support push.":"Push needs https. Open the app over your https address.";return}try{const reg=await pushReg(),sub=reg&&await reg.pushManager.getSubscription(),st=await api("/api/push/status",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({endpoint:sub&&sub.endpoint})});el.textContent=(st.here?"On for this device. ":"Off for this device. ")+st.devices+" device"+(st.devices==1?"":"s")+" in total."}catch(e){el.textContent="Could not check."}}
async function pushOn(){try{if(!("PushManager" in window))return toast("Push needs https and a browser that supports it");if(await Notification.requestPermission()!="granted")return toast("Allow notifications first");const reg=await pushReg();if(!reg)return toast("The app is not ready yet, try again");const k=(await api("/api/push/key")).key;let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:b64u(k)});await api("/api/push/subscribe",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({sub:sub.toJSON(),label:navigator.userAgent.slice(0,60)})});toast("Turned on");pushRefresh()}catch(e){toast("Could not turn on")}}
async function pushOff(){try{const reg=await pushReg(),sub=reg&&await reg.pushManager.getSubscription();if(sub){await api("/api/push/unsubscribe",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({endpoint:sub.endpoint})});await sub.unsubscribe()}toast("Turned off");pushRefresh()}catch(e){toast("Could not turn off")}}
